import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {businessCustomPropertiesSettingsRoute} from './business-custom-properties-settings-route'
import {BusinessPropertiesListRoute} from './BusinessPropertiesListRoute'
import {BusinessSetValuesRoute} from './BusinessSetValuesRoute'

export function BusinessCustomPropertiesSettingsRoute() {
  const {data} = useRouteQuery(businessCustomPropertiesSettingsRoute, 'mainQuery')

  return data.activeTab === 'set-values' ? <BusinessSetValuesRoute /> : <BusinessPropertiesListRoute />
}

try{ BusinessCustomPropertiesSettingsRoute.displayName ||= 'BusinessCustomPropertiesSettingsRoute' } catch {}